96. 	t := jwt.New()
97. 
98. 	for k, v := range claims {
99. 		if err := t.Set(k, v); err != nil {
100. 			return "", err
101. 		}
102. 	}
103. 	hdr := convertHeaders(headers)
104. 
105. 	sig, err = jwt.Sign(t, jwa.SignatureAlgorithm(key.Algorithm()), key, jws.WithHeaders(hdr))
