305. func (n *adapter) startConnecting(newConnector *connector) {
306. 	var resolvedPeerID PeerID
307. 	for {
308. 		if n.shouldConnectTo(newConnector.address, resolvedPeerID) {
309. 			var tlsConfig *tls.Config
310. 			if n.config.tlsEnabled() {
311. 				tlsConfig = &tls.Config{
312. 					Certificates: []tls.Certificate{n.config.ClientCert},
313. 					RootCAs:      n.config.TrustStore,
314. 				}
315. 			}
316. 			if peer, stream, err := newConnector.doConnect(n.config.PeerID, tlsConfig); err != nil {
317. 				waitPeriod := newConnector.backoff.Backoff()
318. 				log.Logger().Infof("Couldn't connect to peer, reconnecting in %d seconds (peer=%s,err=%v)", int(waitPeriod.Seconds()), newConnector.address, err)
319. 				time.Sleep(waitPeriod)
320. 			} else {
321. 				newConnector.backoff.Reset()
322. 				// Since outgoing connections only get the peer's address as input, it doesn't know the peer's ID when initially connecting.
323. 				// We might already have a connection to this peer, in case it connected to the local node first.
324. 				// That's why we store the peer's ID, so we can check whether we're already connected to the peer next time before reconnecting.
325. 				resolvedPeerID = peer.ID
326. 				n.acceptPeer(*peer, stream)
327. 				// When the peer's reconnection timing is very close to the local node's (because they're running the same software),
328. 				// they might reconnect to each other at the same time after a disconnect.
329. 				// So we add a bit of randomness before reconnecting, making the chance they reconnect at the same time a lot smaller.
330. 				time.Sleep(RandomBackoff(time.Second, 5*time.Second))
331. 			}
332. 		}
333. 		// We check whether we should (re)connect to the registered peers every second. Should be OK since it's a cheap check.
334. 		time.Sleep(time.Second)
335. 	}
336. }
