350. 	} else if peerID != "" && n.conns.get(peerID) != nil {
351. 		log.Logger().Tracef("Not connecting since we're already connected to a peer with that ID (peer=%s)", peerID)
352. 		alreadyConnected = true
353. 	}
354. 
355. 	return !alreadyConnected
356. }
